    {
      "stem": "学校图书馆计划购买125套科普读物，每套价格为48元。请问学校一共需要支付多少元？",
      "answer": "6000",
      "solution": "根据题意，总价=单价×数量，即125×48。计算过程：125×48 = 125×8×6 = 1000×6 = 6000（元）。"
    },
    {
      "stem": "一列火车以每小时145千米的速度行驶，从甲地到乙地共行驶了12小时。甲乙两地相距多少千米？",
      "answer": "1740",
      "solution": "根据路程=速度×时间，即145×12。计算过程：145×10=1450，145×2=290，1450+290=1740（千米）。"
    },
    {
      "stem": "某工厂每天生产零件230个，照这样计算，这个工厂在15天内一共能生产多少个零件？",
      "answer": "3450",
      "solution": "总产量=日产量×天数，即230×15。计算过程：230×15 = 230×(10+5) = 2300 + 1150 = 3450（个）。"
    },
    {
      "stem": "一个长方形体育场的长是205米，宽是32米。这个体育场的占地面积是多少平方米？",
      "answer": "6560",
      "solution": "长方形面积=长×宽，即205×32。计算过程：205×32 = 205×(30+2) = 6150 + 410 = 6560（平方米）。"
    },
    {
      "stem": "果园里有108棵苹果树，平均每棵树收获苹果56千克。这个果园今年一共收获了多少千克苹果？",
      "answer": "6048",
      "solution": "总重量=单株产量×株数，即108×56。计算过程：108×56 = (100+8)×56 = 5600 + 448 = 6048（千克）。"
    }
  ]
}
